"""Chart references: what the model is told about charts produced elsewhere."""

import re
from dataclasses import dataclass

_ID_PATTERN = re.compile(r"[a-z0-9][a-z0-9_-]*")


@dataclass(frozen=True, slots=True)
class ChartReference:
    """A chart generated by another source, for the model to place and caption.

    Attributes:
        id: Stable identifier (lowercase letters, digits, ``_`` and ``-``). It becomes the
            ``data-chart-id`` of the empty slot the chart is later dropped into.
        title: Chart title, used as the figure title.
        description: What the chart shows (metric, units, period). Used for the caption and to
            decide where the chart belongs.
    """

    id: str
    title: str
    description: str

    def __post_init__(self) -> None:
        """Validate fields.

        Raises:
            ValueError: If the id is malformed or the title or description is empty.
        """
        if not _ID_PATTERN.fullmatch(self.id):
            raise ValueError(
                f"Invalid chart id {self.id!r}: use lowercase letters, digits, '_' and '-'."
            )
        if not self.title.strip():
            raise ValueError(f"Chart {self.id!r} needs a title.")
        if not self.description.strip():
            raise ValueError(f"Chart {self.id!r} needs a description.")
